import {stages,resources,videos,sources} from './data.js';
import {problems,gradeAnswer} from './problems.js';
import {overview,historyPage,conceptsPage,missionsPage,mistakesPage,glossaryPage,mountGlossary,notebookPage,mountNotebook,exportWorkspace,expansionSources} from './expansion.js';
import {renderLabs,mountLabs} from './labs.js';
import {renderDiagnostic,mountDiagnostic} from './diagnostic.js';

const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='math-prep-v1';
const blank=()=>({saved:[],checks:{},solved:{},notes:[],diagnostic:null});
let state=blank(),storageAvailable=true;
try{const x=JSON.parse(localStorage.getItem(KEY)||'null');if(x&&typeof x==='object'){state.saved=Array.isArray(x.saved)?x.saved.filter(id=>resources.some(r=>r.id===id)):[];state.checks=x.checks&&typeof x.checks==='object'?x.checks:{};state.solved=x.solved&&typeof x.solved==='object'?x.solved:{};state.notes=Array.isArray(x.notes)?x.notes.filter(n=>n&&['id','title','text','type','date'].every(k=>typeof n[k]==='string')):[];state.diagnostic=x.diagnostic||null;}}catch{storageAvailable=false;}
let library={q:'',stage:'all',type:'all',cost:'all',saved:false,picks:false};
let practiceStage='all',problemIndex=0,assisted=false,attempted=false,toastTimer;
const external=(url,label,cls='')=>`<a class="${cls}" href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;
const resource=id=>resources.find(r=>r.id===id);
const intro=(eyebrow,title,desc)=>`<div class="page-intro"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>`;
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2800);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageAvailable=false;toast('Browser storage is unavailable. This session still works.');}$('#saved-count').textContent=state.saved.length;}
function saveButton(r){return `<button class="save-button" data-save="${r.id}" aria-label="${state.saved.includes(r.id)?'Remove from':'Save to'} my shelf: ${escape(r.title)}" aria-pressed="${state.saved.includes(r.id)}">${state.saved.includes(r.id)?'★':'☆'}</button>`;}

function graph(){return `<div class="graph-card"><div class="overline">A SMALL IDEA WITH A BIG FUTURE</div><div class="equation" id="graph-equation">y = 1x + 1</div><div class="graph-legend"><span>INPUT → RELATIONSHIP → OUTPUT</span><span>TRY THE SLIDERS ↓</span></div><svg class="graph" viewBox="0 0 360 235" role="img" aria-labelledby="graph-title graph-description"><title id="graph-title">A line you can change</title><desc id="graph-description">Graph of y equals m x plus b. Sliders control slope and vertical intercept.</desc><defs><pattern id="grid" width="28" height="28" patternUnits="userSpaceOnUse"><path d="M 28 0 L 0 0 0 28" fill="none" stroke="#cbd5c2" stroke-width=".7"/></pattern><clipPath id="graph-clip"><rect x="8" y="8" width="344" height="214"/></clipPath></defs><rect x="8" y="8" width="344" height="214" fill="url(#grid)"/><path d="M8 180H352 M68 8V222" stroke="#6e8169" stroke-width="1.2"/><g fill="#52664e" font-family="monospace" font-size="9"><text x="55" y="194">0</text><text x="205" y="194">5</text><text x="46" y="45">5</text><text x="343" y="194">x</text><text x="57" y="19">y</text></g><g clip-path="url(#graph-clip)"><path id="graph-line" fill="none" stroke="#285a45" stroke-width="3"/><circle id="graph-point" r="5" fill="#a14b2d" stroke="#f5f3ed" stroke-width="2"/></g></svg><div class="graph-controls"><label for="slope">SLOPE m <output id="slope-value">1</output><input type="range" id="slope" min="-2" max="3" value="1" step="0.5"></label><label for="intercept">STARTING VALUE b <output id="intercept-value">1</output><input type="range" id="intercept" min="-2" max="4" value="1" step="0.5"></label></div><p class="graph-caption" id="graph-caption"></p></div>`;}
function home(){return overview(state);}


function path(stageId){const s=stages.find(x=>x.id===stageId)||stages[0];return `${intro('THE LEARNING PATH','From numbers to relationships.','Start at the earliest skill that breaks down on fresh problems. Use checks to skip material you already know, and return when a later topic reveals a gap.')}<div class="stage-layout"><div class="stages" aria-label="Learning stages">${stages.map(x=>`<a class="stage-button ${x.id===s.id?'active':''}" href="#path/${x.id}" ${x.id===s.id?'aria-current="step"':''} style="text-decoration:none"><span class="num">${x.n}</span><span><b>${x.title}</b><small>${x.tag}</small></span></a>`).join('')}</div><article class="stage-detail"><span class="stage-num">STAGE ${s.n} / ${s.tag.toUpperCase()}</span><h2>${s.title}</h2><p class="smallprint">${s.time}</p><p class="idea">${s.idea}</p><p class="why">${s.why}</p><h3>What to learn</h3><ul class="topic-list">${s.topics.map(t=>`<li>${t}</li>`).join('')}</ul><div class="example"><span>MAKE IT CONCRETE</span><p>${s.example}</p></div><h3>Your main resources</h3><div class="resource-pair">${[s.book,s.practice].map(id=>{const r=resource(id);return external(r.url,`<small>${r.type==='Book'?'READ & WORK EXAMPLES':'PRACTISE & CHECK'}</small>${r.title}`);}).join('')}</div><p class="muted">${s.chapters}</p><h3>Can you do it with the book closed?</h3><p class="smallprint">These are self-checks, not a graded assessment or proof of mastery.</p><div class="checklist">${s.check.map((c,i)=>`<label><input type="checkbox" data-check="${s.id}-${i}" ${state.checks[`${s.id}-${i}`]?'checked':''}><span>${c}</span></label>`).join('')}</div><p class="check-count" id="stage-count">${s.check.filter((_,i)=>state.checks[`${s.id}-${i}`]).length} OF ${s.check.length} SELF-CHECKS MARKED</p><div class="note"><b>When to move forward</b><p>${s.gate}</p></div><div class="actions"><a class="btn primary" href="#practice/${s.id}">Try a few original problems →</a><a class="text-link" href="#library/${s.id}">See related resources</a></div></article></div><section class="section dual"><article class="essay"><h3>A useful readiness rule</h3><p>Try a fresh mixed set without notes. Aim for roughly 80–90% correct, then try another set after a delay. Explain your method and repair repeated errors.</p><p>This threshold is a practical suggestion, not a validated placement standard. A high score on copied examples is weaker evidence than success on varied, unfamiliar problems.</p></article><article class="essay"><h3>Let college requirements set the course.</h3><p>Use the rest of 2026 to strengthen the foundation at a sustainable pace. For a spring 2027 start, choose your class through Southwestern’s current placement process. You do not need to force an entire self-study sequence into the remaining weeks.</p><p>${external('https://www.swccd.edu/student-support/placement-and-prerequisites/placement-guide/index.aspx','Check Southwestern’s placement guide')}</p></article></section>`;}

function card(r){return `<article class="resource-card"><div class="card-top"><div class="chips"><span class="chip">${r.type}</span><span class="chip">${r.cost}</span>${r.pick?'<span class="chip pick">CORE PICK</span>':''}</div>${saveButton(r)}</div><h3>${r.title}</h3><div class="byline">${r.by}</div><div class="role">${r.role}</div><p>${r.desc}</p><details><summary>How to use it & what to watch for</summary><p><strong>Use it this way.</strong> ${r.use}</p><p><strong>Keep in mind.</strong> ${r.caution}</p></details><div class="actions">${external(r.url,r.label,'text-link')}</div>${r.extra?external(r.extra.url,r.extra.text,'extra'):''}</article>`;}
function libraryPage(){return `${intro('THE RESOURCE LIBRARY','Choose a small, useful stack.','Keep one main sequence. Add an alternative explanation only when it solves a real difficulty. These resources have different jobs; you do not need to complete them all.')}<div class="note library-note"><b>My default recommendation: OpenStax + Khan Academy + written work.</b><p>Mathispower4u supplies short explanations when needed. Desmos helps with graphs later. If you choose Math Academy or ALEKS, let that become the main practice sequence instead of adding another full program.</p></div><div class="filters"><label class="search-field" for="resource-search">SEARCH<input type="search" id="resource-search" placeholder="Try fractions, videos, or OpenStax…" value="${escape(library.q)}"></label><label for="stage-filter">STAGE<select id="stage-filter"><option value="all">All stages</option>${stages.map(s=>`<option value="${s.id}" ${library.stage===s.id?'selected':''}>${s.title}</option>`).join('')}</select></label><label for="type-filter">FORMAT<select id="type-filter"><option value="all">All formats</option>${['Book','Practice','Video','Tool','Course','Guide'].map(t=>`<option ${library.type===t?'selected':''}>${t}</option>`).join('')}</select></label><label for="cost-filter">COST<select id="cost-filter"><option value="all">Free + paid</option>${['Free','Paid'].map(c=>`<option ${library.cost===c?'selected':''}>${c}</option>`).join('')}</select></label></div><div class="pill-row"><button id="picks-only" class="${library.picks?'active':''}" aria-pressed="${library.picks}">Core picks only</button><button id="saved-only" class="${library.saved?'active':''}" aria-pressed="${library.saved}">My saved shelf</button><button id="clear-filters">Clear filters</button></div><div class="filter-summary"><span id="resource-count" aria-live="polite"></span><span>Prices checked October 2026 · confirm before buying.</span></div><div class="resource-grid" id="resource-grid"></div><section class="section note"><b>For physical books, buy the next useful book.</b><p>A used copy of Lial’s Basic College Mathematics is an optional arithmetic alternative. Stewart’s Precalculus belongs later. Check the edition and answer support before buying. OpenStax PDFs can serve you immediately for free.</p></section>`;}
function renderResources(){const q=library.q.toLowerCase().trim();const filtered=resources.filter(r=>(library.stage==='all'||r.levels.includes(library.stage)||r.levels.includes('all'))&&(library.type==='all'||r.type===library.type)&&(library.cost==='all'||r.cost===library.cost)&&(!library.saved||state.saved.includes(r.id))&&(!library.picks||r.pick)&&(!q||`${r.title} ${r.by} ${r.desc} ${r.role} ${r.levels.join(' ')}`.toLowerCase().includes(q)));$('#resource-count').textContent=`${filtered.length} of ${resources.length} resources${library.saved?' · saved shelf':''}`;$('#resource-grid').innerHTML=filtered.length?filtered.map(card).join(''):`<div class="empty" style="grid-column:1/-1"><h3>${library.saved?'Your shelf is ready when you are.':'No matching resources.'}</h3><p class="muted" style="margin-top:10px">${library.saved?'Use the star on any resource to save it here.':'Try a broader search or clear a filter.'}</p></div>`;}

function method(){return `${intro('HOW TO LEARN','Read a little. Work it out. Return.','You are building the ability to choose a method, carry it out, and explain why it works. Reading, examples, independent practice, feedback, and later recall each contribute something different.')}<article class="essay"><h3>Your 30 / 30 idea is a reasonable start.</h3><p>Thirty minutes reading and thirty minutes solving can work. My usual adjustment is to give independent work more of the hour. Treat this as an adjustable example, not an evidence-backed “optimal” ratio.</p><div class="method-ratio"><div class="learn"><b>20 min</b><span>Read + reconstruct an example</span></div><div class="solve"><b>35 min</b><span>Solve, check, and correct</span></div><div class="review"><b>5 min</b><span>Recall + note a gap</span></div></div><p class="smallprint">On a new topic, you may need more explanation. On review, most of the time can be spent solving. Reading an example with a pencil is already active work.</p></article><section class="section"><div class="section-head"><h2>The learning loop.</h2><p>A reusable way to study a section, without turning your life into a timetable.</p></div><div class="steps">${[
 ['Understand one small idea','Read a short explanation and one worked example. Say what each symbol means. Ask why the main step is allowed. Avoid reading an entire chapter before attempting anything.'],
 ['Reconstruct the example','Cover the worked solution and try it yourself. If you get stuck, reveal only enough to identify the missing step, then continue. This is practice at retrieving the method, not copying it.'],
 ['Attempt a fresh problem','Work a few related problems while the idea is new. Show the steps. Use a diagram or concrete numbers if the symbols feel slippery. Try before asking for a hint.'],
 ['Check and repair the cause','Compare with a reliable answer or explanation. Record the first wrong step and its cause: a missing fact, a sign error, an unjustified operation, or a misunderstood question. Then solve a new similar problem.'],
 ['Mix and revisit','Once the basic method is familiar, combine it with previously learned topics. Return after a delay. Choosing the appropriate method is a separate skill from repeating the same method ten times.']
 ].map(([h,p])=>`<article class="method-step"><div><h3>${h}</h3><p>${p}</p></div></article>`).join('')}</div><p class="inline-sources">Evidence and teaching guidance: ${external('https://ies.ed.gov/ncee/wwc/PracticeGuide/1','IES practice guide')} ${external('https://www.math.ucdavis.edu/resources/learning/math-study-tips','UC Davis study tips')}</p></section><section class="section dual"><article class="essay"><h3>What to do when stuck</h3><p>Make a real attempt. For a routine beginner exercise, several focused minutes may be enough to identify that you need help; a substantial problem may deserve longer. Ask for one hint, a simpler example, or the first mistaken step.</p><p>Take a break when effort stops producing new ideas. Return to the prerequisite later if it repeatedly blocks progress. There is no useful universal rule to struggle for an hour or to give up after exactly five minutes.</p></article><article class="essay"><h3>Use tools to improve your thinking</h3><p>Before a calculator or graphing tool, estimate or predict. Before an AI explanation, make an attempt and identify the step you do not understand. Ask for a hint or a new similar problem, then verify with a trusted source.</p><p>An explanation that sounds clear can still contain an error. The independent follow-up problem tells you more than how convincing the explanation felt.</p></article></section><section class="section"><div class="section-head"><div><div class="eyebrow">THE MATH SORCERER</div><h2>Keep the useful ideas.<br>Read the titles in context.</h2></div><p>These are among the most-viewed relevant videos on his Popular list. Counts are rounded snapshots, not measures of teaching effectiveness.</p></div>${videos.map(v=>`<article class="video-row"><div><h3>${external(v.url,v.title)}</h3><div class="views">${v.views} VIEWS · CHECKED OCT 30, 2026</div></div><div><p>${v.take}</p><p class="smallprint">${v.note}</p></div></article>`).join('')}</section><section class="section note"><b>For this engineering route, choose the algebra entry point.</b><p>Proofs and discrete mathematics can be interesting side explorations. They are not prerequisites for rebuilding arithmetic. The large book collections in the videos show possible paths, not a requirement to purchase every title.</p></section><section class="section"><div class="section-head"><h2>What other teachers add.</h2></div><div class="recommended"><article class="start-card"><span class="number">PAUL DAWKINS / LAMAR</span><h3>Work with the formula.</h3><p>Learn what a formula says, when it applies, and how to use it. Keep problem solving at the center of study.</p>${external('https://tutorial.math.lamar.edu/Extras/StudyMath/HowToStudyMath.aspx','Read his advice')}</article><article class="start-card"><span class="number">BARBARA OAKLEY</span><h3>Recall and reconnect.</h3><p>Close the page, retrieve an idea, explain it in simple language, and revisit it over time. Breaks can be part of useful study.</p>${external('https://barbaraoakley.com/wp-content/uploads/2016/12/ECS_GoodStudyPoster_36x48_PRINT.pdf','Read the principles')}</article><article class="start-card"><span class="number">UC DAVIS / IES</span><h3>Practise remembering.</h3><p>Use questions, delayed review and varied practice. A skill that feels easy immediately after an example may not yet be secure.</p>${external('https://www.math.ucdavis.edu/resources/learning/math-study-tips','Explore the study tips')}</article></div><p class="smallprint" style="margin-top:18px">Research supports these broad principles, but it does not establish one universally best app or minute-by-minute routine for an adult returning to math.</p></section>`;}

function practicePool(){return problems.filter(p=>practiceStage==='all'||p.stage===practiceStage);}
function practicePage(){const pool=practicePool(),p=pool[problemIndex%pool.length];assisted=false;attempted=false;return `${intro('THE PRACTICE BENCH','A place to try, not perform.','Use paper for your reasoning. These original examples let you inspect a skill, see a hint, and understand the solution. This small set supplements a full course; it is not a placement test.')}<div class="filters"><label for="practice-stage">CHOOSE A TOPIC<select id="practice-stage"><option value="all">Mixed foundations + preview</option>${stages.map(s=>`<option value="${s.id}" ${practiceStage===s.id?'selected':''}>${s.title}${s.id==='precalculus'?' · later preview':''}</option>`).join('')}</select></label><span class="smallprint">${problems.length} original problems · fractions and decimals accepted</span></div><div class="practice-layout"><article class="problem-card"><div class="overline">${stages.find(s=>s.id===p.stage).title} / ${problemIndex%pool.length+1} OF ${pool.length}</div><h2>${p.name}</h2><div class="problem-question">${p.q}</div><form id="answer-form"><label class="answer-label" for="answer">Your answer — number only, in the requested units</label><div class="answer-row"><input id="answer" type="text" autocomplete="off" spellcheck="false" placeholder="e.g. 3/4, 0.75, or −2" aria-describedby="answer-format feedback"><button class="btn primary" type="submit">Check answer →</button></div><p class="smallprint" id="answer-format" style="margin-top:8px">For repeating decimals, round to at least four decimal places. Do not enter units or equations.</p></form><div id="feedback" aria-live="polite"></div><div class="actions"><button class="btn" id="hint-button">Give me a hint</button><button class="btn" id="solution-button">Show the explanation</button><button class="btn" id="next-problem">Next problem →</button></div><div id="hint-area"></div><div id="solution-area"></div></article><aside class="practice-aside"><div class="eyebrow">A SMALL WORKBENCH</div><h3>Show your thinking.</h3><p>Write what you know, what you need, and why each step follows.</p><div class="big-number" id="solved-number">${Object.keys(state.solved).filter(id=>problems.some(p=>p.id===id)).length}<span style="font-size:20px"> / ${problems.length}</span></div><p>Different problems answered correctly in this browser. Helped attempts count too; this is practice history, not a mastery score.</p><hr class="rule"><p><b>If it felt difficult:</b> follow the resource link for this topic, then try again later.</p><div class="actions"><a class="text-link" href="#path/${p.stage}">Review ${stages.find(s=>s.id===p.stage).title} →</a></div></aside></div><div class="section note"><b>Ask three questions after a solution.</b><p>Why was that operation allowed? How could I check the result? What small change to the question would require a different approach?</p></div>`;}
function showSolution(p){$('#solution-area').innerHTML=`<section class="solution"><div class="overline">WORK THROUGH THE REASONING</div><div class="answer">${p.display}</div><ol>${p.steps.map(s=>`<li>${s}</li>`).join('')}</ol><div class="note"><b>The idea</b><p>${p.why}</p></div><p class="smallprint" style="margin-top:17px"><b>A common trap:</b> ${p.pitfall}</p></section>`;}

function horizon(){return `${intro('THE BIGGER PICTURE','The foundations travel with you.','The early mathematics serves aerospace, robotics, ocean systems and space habitats. You can keep that destination in view while giving today’s small ideas your full attention.')}<div class="horizon-grid">${[
 ['Ratios → scale and rate','3/4 L per minute','Fractions later describe fuel fractions, mixtures, gear ratios, efficiency, and rates. The same idea becomes more useful as the surrounding context grows.','Now: understand the quantity, the ratio, and its units.'],
 ['Algebra → relationships','d = vt','Algebra helps you express a relationship and solve for the quantity you need. In a simple constant-speed model, distance connects speed and time.','Now: translate words into equations and justify each rearrangement.'],
 ['Geometry → shape and space','c² = a² + b²','Dimensions, angles and scale appear in mechanisms, structures and navigation. Later, vectors and coordinate systems extend these geometric ideas.','Now: draw a clear diagram and distinguish length, area and volume.'],
 ['Functions → changing systems','y = f(t)','A function can represent a sensor’s output, a vehicle’s position, or a thermal model. The formula and graph provide complementary information.','Now: connect input, output, equation, table and graph.']
 ].map(([h,f,p,n])=>`<article class="horizon-card"><h3>${h}</h3><div class="formula">${f}</div><p>${p}</p><p><b>${n}</b></p></article>`).join('')}</div><section class="section"><div class="section-head"><h2>The mathematics that comes later.</h2><p>This is a conceptual map. Your degree’s course sequence and prerequisites decide the actual enrollment order.</p></div><div class="long-path"><div><span>FOUNDATION / NOW</span><h3>Arithmetic & algebra</h3><p>Reliable manipulation, ratios, equations, graphs, and functions.</p></div><div><span>BRIDGE / NEXT</span><h3>Precalculus & trigonometry</h3><p>Function families, angles, periodic relationships, and preparation for calculus.</p></div><div><span>COLLEGE CORE</span><h3>Calculus, linear algebra & differential equations</h3><p>Change, accumulation, vectors, transformations, and models of evolving systems.</p></div><div><span>ENGINEERING USE</span><h3>Mechanics, controls & simulation</h3><p>Use mathematics with physics, computation, experimentation, and engineering judgment.</p></div></div></section><section class="section dual"><article class="essay"><h3>Think like an engineer, even here.</h3><p>Before calculating, name the quantities and their units. Make a rough estimate. Draw the situation. After calculating, ask whether the sign and size make sense.</p><p>For example, a result of 10,000 liters for a small bottle should trigger a unit or decimal check before you trust the arithmetic.</p></article><article class="essay"><h3>Keep your destination flexible.</h3><p>A tentative 2033 graduation and longer-term space ambitions can motivate the work. They do not require choosing a narrow specialty before you have taken the foundational classes.</p><p>These tools remain useful whether you later prefer spacecraft, robotic systems, structures, propulsion, or life-support engineering.</p></article></section><section class="section note"><b>Your immediate objective is dependable fundamentals.</b><p>Self-study can improve readiness before Southwestern. Once enrolled, use the syllabus, assigned work, tutoring, and instructor feedback to set priorities. Preparation is part of the journey; there is no need to become a complete engineer before beginning college.</p></section><div class="actions"><a class="btn primary" href="#path">Back to the next useful skill →</a><a class="text-link" href="/aero_specialization_decision">Explore the aerospace field guide ↗</a></div>`;}

function sourcesPage(){return `${intro('RESEARCH & SOURCES','Recommendations you can inspect.','The guide combines official curriculum and publisher pages, teacher advice, learning research, and The Math Sorcerer’s videos. Resource selection and the proposed study loop are editorial judgments tailored to this goal.')}<div class="dual"><div class="note"><b>What is established</b><p>Broad evidence supports spaced practice, retrieval, explanatory questions, and using worked examples alongside independent problems. Course pages and book prefaces establish what a resource contains.</p></div><div class="note warn"><b>What is a recommendation</b><p>The 20 / 35 / 5 split, approximate 80–90% readiness check, preferred books, and combination of tools are practical suggestions. They are not validated placement rules or guarantees of a completion date.</p></div></div><section class="section">${sources.map(s=>`<article class="source-row"><div><h3>${external(s.url,s.title)}</h3><small>${s.kind}</small></div><p>${s.detail}</p></article>`).join('')}</section><section class="section essay"><h3>About the resource choices</h3><p>Last substantive review: October 31, 2026. Prices and platform offerings may change. The library links to publishers and providers without affiliate tracking. It does not reproduce the books or imply that each optional title is required.</p><p>The two supplied start-to-finish video transcripts were read for their relevant early-math advice. The official Popular list and accessible video text were inspected. Where a full transcript was unavailable, the guide says so rather than treating an automated summary as the creator’s words.</p><p>Practice questions and explanations were written for this site. They are a small, reviewed sample rather than a comprehensive diagnostic. Self-checks, bookmarks and correct-answer history are saved locally in this browser when storage is available; no account is required.</p><div class="actions"><button class="btn" id="export-progress">Export my shelf & checks</button>${external('https://github.com/ChrisTrovato/math-prep','View the source','text-link')}</div><p class="smallprint" id="storage-status">${storageAvailable?'Browser storage is available.':'Storage is unavailable; progress may last only for this session.'}</p></section>`;}

function initializeGraph(){const update=()=>{const m=Number($('#slope').value),b=Number($('#intercept').value);$('#slope-value').textContent=m;$('#intercept-value').textContent=b;$('#graph-equation').textContent=`y = ${m}x ${b<0?'−':'+'} ${Math.abs(b)}`;const y=x=>180-28*(m*x+b),x=v=>68+28*v;$('#graph-line').setAttribute('d',`M${x(-3)} ${y(-3)}L${x(11)} ${y(11)}`);$('#graph-point').setAttribute('cx',68);$('#graph-point').setAttribute('cy',y(0));$('#graph-caption').textContent=`For each +1 in x, y ${m<0?'decreases by':m>0?'increases by':'changes by'} ${Math.abs(m)}. At x = 0, y = ${b}.`;$('#graph-description').textContent=`Line with slope ${m} and y intercept ${b}.`;};$('#slope').addEventListener('input',update);$('#intercept').addEventListener('input',update);update();}
function initializeLibrary(){renderResources();$('#resource-search').addEventListener('input',e=>{library.q=e.target.value;renderResources();});for(const [id,key]of[['stage-filter','stage'],['type-filter','type'],['cost-filter','cost']])$('#'+id).addEventListener('change',e=>{library[key]=e.target.value;renderResources();});for(const [id,key]of[['picks-only','picks'],['saved-only','saved']])$('#'+id).addEventListener('click',e=>{library[key]=!library[key];e.currentTarget.classList.toggle('active',library[key]);e.currentTarget.setAttribute('aria-pressed',library[key]);renderResources();});$('#clear-filters').addEventListener('click',()=>{library={q:'',stage:'all',type:'all',cost:'all',saved:false,picks:false};$('#main').innerHTML=libraryPage();initializeLibrary();});}
function initializePractice(){const p=practicePool()[problemIndex%practicePool().length];$('#practice-stage').addEventListener('change',e=>{practiceStage=e.target.value;problemIndex=0;$('#main').innerHTML=practicePage();initializePractice();});$('#answer-form').addEventListener('submit',e=>{e.preventDefault();const outcome=gradeAnswer(p,$('#answer').value);const feedback=$('#feedback');if(outcome==='invalid'){feedback.className='feedback retry';feedback.textContent='Enter a number or a simple fraction such as 3/4. Leave off units and equations.';return;}if(outcome==='correct'){feedback.className='feedback good';feedback.textContent='That is correct. Now explain why the method works, then compare your reasoning below.';state.solved[p.id]={helped:assisted||attempted,date:new Date().toISOString().slice(0,10)};persist();showSolution(p);if($('#solved-number'))$('#solved-number').innerHTML=`${Object.keys(state.solved).filter(id=>problems.some(x=>x.id===id)).length}<span style="font-size:20px"> / ${problems.length}</span>`;}else{attempted=true;feedback.className='feedback retry';feedback.textContent='Not quite. Recheck the requested quantity, signs, and units. You can try again or ask for one hint.';}});$('#hint-button').addEventListener('click',()=>{assisted=true;$('#hint-area').innerHTML=`<div class="feedback retry"><b>One hint:</b> ${p.hint}</div>`;});$('#solution-button').addEventListener('click',()=>{assisted=true;showSolution(p);});$('#next-problem').addEventListener('click',()=>{problemIndex=(problemIndex+1)%practicePool().length;$('#main').innerHTML=practicePage();initializePractice();$('#answer').focus({preventScroll:true});});}
let routeCleanup=null;
const routeLabels={home:'Overview',path:'Learning path',diagnostic:'Placement check',concepts:'Concept atlas',history:'History of math',glossary:'Symbols & glossary',method:'How to learn',missions:'Aerospace examples',labs:'Interactive labs',practice:'Practice bench',mistakes:'Mistake lab',library:'Resource library',notebook:'My workspace',horizon:'What comes next',sources:'Research & sources'};
function closeMenu(){document.body.classList.remove('menu-open');$('#menu-toggle').setAttribute('aria-expanded','false');}
function renderRoute(){
  if(routeCleanup){routeCleanup();routeCleanup=null;}
  const [raw,encodedArg]=location.hash.slice(1).split('/');
  let arg='';try{arg=decodeURIComponent(encodedArg||'');}catch{}
  const view=Object.hasOwn(routeLabels,raw)?raw:'home';
  if(view==='library'){library.stage=stages.some(s=>s.id===arg)?arg:'all';library.saved=arg==='saved';library.cost=arg==='paid'?'Paid':'all';library.q='';library.type='all';library.picks=false;}
  if(view==='practice'){practiceStage=stages.some(s=>s.id===arg)?arg:'all';problemIndex=0;}
  const renderers={home,path:()=>path(arg),library:libraryPage,method,practice:practicePage,horizon,sources:()=>sourcesPage()+expansionSources(),history:()=>historyPage(arg),concepts:()=>conceptsPage(arg),missions:()=>missionsPage(arg),mistakes:mistakesPage,glossary:glossaryPage,notebook:()=>notebookPage(state,arg),labs:()=>renderLabs(arg||'power'),diagnostic:()=>'<div id="diagnostic-host">'+renderDiagnostic(state.diagnostic)+'</div>'};
  $('#main').innerHTML=renderers[view]();
  $$('#primary-nav a').forEach(a=>{if(a.hash==='#'+view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
  $('#page-label').textContent=routeLabels[view];document.title=routeLabels[view]+' — Math Prep';
  if(view==='library')initializeLibrary();
  if(view==='practice')initializePractice();
  if(view==='sources')$('#export-progress').addEventListener('click',()=>exportWorkspace(state));
  if(view==='glossary')mountGlossary($('#main'));
  if(view==='notebook')mountNotebook($('#main'),state,persist,toast);
  if(view==='labs')routeCleanup=mountLabs($('#main'));
  if(view==='diagnostic')routeCleanup=mountDiagnostic($('#diagnostic-host'),{session:state.diagnostic,onSave:s=>{state.diagnostic=s;persist();},onNavigate:hash=>{location.hash=hash;}});
  closeMenu();window.scrollTo({top:0,behavior:'instant'});
}
$('#menu-toggle').addEventListener('click',()=>{const open=document.body.classList.toggle('menu-open');$('#menu-toggle').setAttribute('aria-expanded',String(open));});
$('#menu-scrim').addEventListener('click',closeMenu);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();}});

document.addEventListener('click',e=>{const btn=e.target.closest('[data-save]');if(!btn)return;const id=btn.dataset.save,wasSaved=state.saved.includes(id);state.saved=wasSaved?state.saved.filter(x=>x!==id):[...state.saved,id];persist();btn.setAttribute('aria-pressed',!wasSaved);btn.setAttribute('aria-label',`${wasSaved?'Save to':'Remove from'} my shelf: ${resource(id).title}`);btn.textContent=wasSaved?'☆':'★';if(library.saved&&$('#resource-grid'))renderResources();toast(wasSaved?'Removed from your shelf.':'Saved to your shelf in this browser.');});
document.addEventListener('change',e=>{if(!e.target.matches('[data-check]'))return;state.checks[e.target.dataset.check]=e.target.checked;persist();const s=stages.find(s=>e.target.dataset.check.startsWith(s.id+'-'));if(s&&$('#stage-count'))$('#stage-count').textContent=`${s.check.filter((_,i)=>state.checks[`${s.id}-${i}`]).length} OF ${s.check.length} SELF-CHECKS MARKED`;});
window.addEventListener('hashchange',()=>{renderRoute();$('#main').focus({preventScroll:true});});
$('.skip-link').addEventListener('click',e=>{e.preventDefault();$('#main').focus();});
$('#saved-count').textContent=state.saved.length;
renderRoute();
